import React from 'react';

import { Link } from 'react-router-dom';

import {
  addEquipToSetSeveral,
  getEquipSetItems,
  getOneEquipSetById,
  removeEquipFromSetSeveral,
} from '@apps/Hiking/@services/equip.service';
import { IEquipSet, ISetEquip } from '@apps/Hiking/@types/equip.types';
import { addEquipToSetModal } from '@apps/Hiking/equip/HikingEquip/addEquipToSet/addEduipToSetModal';
import { previewEquipModal } from '@apps/Hiking/equip/HikingEquip/previewEquip/previewEduipModal';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import BackpackVertical from '../components/BackpackVertical';
import EquipListItem from '../components/EquipListItem';
import { editEquipSetParams } from '../components/EquipSetEditParams';

const EquipPageSetOne: React.FC<{ id_set: number }> = ({ id_set }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [items, setItems] = React.useState<ISetEquip[]>([]);
  const [data, setData] = React.useState<IEquipSet | null>(null);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getOneEquipSetById(id_set);
      setData(res);
      const res1 = await getEquipSetItems(id_set);
      setItems(res1);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_set]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  if (!data) return <PohAlert variant={AlertVariant.Danger}>Has no equip set</PohAlert>;

  const handleEditItems = async () => {
    const alreadyAdded = items.map((x) => x.id);
    addEquipToSetModal(async (selectedItems) => {
      const onlyDelIds = alreadyAdded.filter(
        (id) => !selectedItems.map(({ id: siid }) => siid).includes(id),
      );
      const onlyNewIds = selectedItems
        .map(({ id }) => id)
        .filter((id) => !alreadyAdded.includes(id));

      let deletedResult = false;
      let addResult = false;

      if (onlyDelIds.length) {
        const { success: res } = await removeEquipFromSetSeveral(id_set, onlyDelIds);

        deletedResult = res;
      }

      if (onlyNewIds.length) {
        const { success: res } = await addEquipToSetSeveral(id_set, onlyNewIds);

        addResult = res;
      }

      if (deletedResult || addResult) {
        getEquipSetItems(id_set).then(setItems).catch(err);
      }
    }, alreadyAdded);
  };

  return (
    <div>
      <PohBreadcrumbs
        data={[
          { href: '/equip', text: 'Снаряжение' },
          { href: '/equip/sets', text: 'Сборки' },
          { href: '/equip/sets/' + id_set, text: data.name, active: true },
        ]}
      />

      <PohContainer>
        <PageHeader title={data.name}>
          <PohButton
            size={ButtonSize.Small}
            className="me-2"
            onClick={async () => {
              const edited = await editEquipSetParams(data);
              notificationHelper.success('Сохранено');
              setData({ ...data, ...edited });
            }}
          >
            Редактировать
          </PohButton>
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={handleEditItems}
          >
            Элементы
          </PohButton>
        </PageHeader>

        <p className="mt-n3">
          <small>{data.description}</small>
        </p>
        <PohRow>
          <PohCol sm={9}>
            {items.length === 0 && <Empty>Пока тут пусто...</Empty>}
            {items.length > 0 && (
              <PohList
                data={items.map((item) => {
                  return {
                    key: item.id,

                    children: (
                      <Link to={`/equip/${item.id}`} className="text-body">
                        <EquipListItem item={item} />
                      </Link>
                    ),
                    onClick: (e) => e.altKey && previewEquipModal(item),
                  };
                })}
              />
            )}
          </PohCol>
          <PohCol sm={3}>
            {data.backpack && (
              <>
                <BackpackVertical backpack={data.backpack}></BackpackVertical>
                <p className="text-center">
                  <Link to={`/equip/backpacks/${data.backpack.id}`}>Страница рюкзака</Link>
                </p>
              </>
            )}
          </PohCol>
        </PohRow>
      </PohContainer>
    </div>
  );
};

export default EquipPageSetOne;
